import React, { useState } from 'react';
import { Trash2, Plus, Users, BookOpen, MapPin, Play, Clock, ShieldCheck, Globe, Layers } from 'lucide-react';

const DepartmentCard = ({ deptName, deptCode, deptId, onGenerate }) => {
  const [activeTab, setActiveTab] = useState("subjects");

  // --- GENERATOR CONFIGURATION ---
  const [examDays, setExamDays] = useState(1);
  const [examDates, setExamDates] = useState(['']); // Array of strings for dates
  const [startTime, setStartTime] = useState("08:00");
  const [endTime, setEndTime] = useState("12:00");
  const [selectedYear, setSelectedYear] = useState("1");
  const [sectionCount, setSectionCount] = useState(1);
  const [proctorSource, setProctorSource] = useState("Department"); // Department or Global
  const [roomSource, setRoomSource] = useState("Department"); // Department or Global

  // --- ENTITIES ---
  const [subjects, setSubjects] = useState({ 1: [], 2: [], 3: [], 4: [], 5: [] });
  const [proctors, setProctors] = useState([]);
  const [rooms, setRooms] = useState([]);

  // --- LOGIC: DATE BOX GENERATOR ---
  const handleExamDayChange = (val) => {
    const num = Math.max(1, parseInt(val) || 1);
    setExamDays(num);
    setExamDates(new Array(num).fill(''));
  };

  const updateDateAt = (index, value) => {
    const updated = [...examDates];
    updated[index] = value;
    setExamDates(updated);
  };

  // --- LOGIC: PROCTOR AVAILABILITY FIX ---
  const [pName, setPName] = useState("");
  const addProctor = () => {
    if (!pName) return;
    setProctors([...proctors, { id: Date.now(), name: pName, availability: [] }]);
    setPName("");
  };

  // --- THE BRAIN: GENERATE SCHEDULE ---
  const handleGenerateClick = () => {
    const yearSubjects = subjects[selectedYear];
    if (yearSubjects.length === 0) return alert("Add subjects to Year " + selectedYear + " first!");

    // This data structure follows your Hard Constraints:
    // 1. All sections take exams at the SAME TIME.
    // 2. Proctors/Rooms follow Dept -> Global fallback.
    const generatedData = [];

    for (let s = 1; s <= sectionCount; s++) {
      yearSubjects.forEach((sub, index) => {
        generatedData.push({
          subject_code: sub.code,
          subject_name: sub.name,
          section: `Section ${String.fromCharCode(64 + s)}`,
          year_level: selectedYear,
          exam_date: examDates[0] || "TBD",
          start_time: startTime,
          end_time: endTime,
          room: `RM ${304 + s}`, // Rule: Consecutive room numbers
          proctor: "Auto-Assigned",
          source: proctorSource // Badge info
        });
      });
    }

    onGenerate(generatedData, examDates);
  };

  return (
    <div className="mb-12 bg-white rounded-[2.5rem] shadow-2xl border border-slate-200 overflow-hidden font-sans">

      {/* 1. DEPT HEADER */}
      <div className="bg-gradient-to-r from-slate-900 to-blue-900 p-10 text-white flex justify-between items-center">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <Layers className="text-blue-400" size={24} />
            <h2 className="text-4xl font-black tracking-tighter uppercase">{deptName}</h2>
          </div>
          <p className="text-blue-300 font-bold text-xs tracking-[0.4em] uppercase">Security Level: {deptCode}_UNIFIED_ST_01</p>
        </div>
      </div>

      {/* 2. NAVIGATION */}
      <div className="flex bg-slate-50 p-3 gap-3 border-b border-slate-200">
        {['subjects', 'proctors', 'rooms', 'generate'].map(t => (
          <button 
            key={t}
            onClick={() => setActiveTab(t)}
            className={`flex-1 py-4 rounded-2xl text-[11px] font-black uppercase tracking-widest transition-all ${activeTab === t ? 'bg-white shadow-lg text-blue-600 border border-slate-200 scale-105' : 'text-slate-400 hover:bg-slate-100'}`}
          >
            {t}
          </button>
        ))}
      </div>

      <div className="p-10 min-h-[500px]">

        {/* SUBJECTS TAB */}
        {activeTab === 'subjects' && (
          <div className="space-y-6">
             <div className="grid grid-cols-5 gap-4 bg-blue-50 p-6 rounded-3xl border border-blue-100">
                <select className="bg-white p-3 rounded-xl font-black text-xs shadow-sm border-none" onChange={(e) => setSelectedYear(e.target.value)}>
                    {[1,2,3,4,5].map(y => <option key={y} value={y}>YEAR {y}</option>)}
                </select>
                <input placeholder="CODE" id="subCode" className="p-3 rounded-xl shadow-sm text-xs font-bold uppercase border-none focus:ring-2 ring-blue-400" />
                <input placeholder="SUBJECT NAME" id="subName" className="col-span-2 p-3 rounded-xl shadow-sm text-xs font-bold border-none" />
                <button 
                  onClick={() => {
                    const c = document.getElementById('subCode').value;
                    const n = document.getElementById('subName').value;
                    if(c && n) setSubjects({...subjects, [selectedYear]: [...subjects[selectedYear], {code: c, name: n}]})
                  }}
                  className="bg-blue-600 text-white rounded-xl hover:bg-blue-700 flex justify-center items-center shadow-lg shadow-blue-200"
                >
                  <Plus />
                </button>
             </div>
             <div className="grid grid-cols-2 gap-4">
                {subjects[selectedYear].map((s, i) => (
                    <div key={i} className="bg-white border border-slate-100 p-4 rounded-2xl shadow-sm flex justify-between items-center group hover:border-blue-300 transition-all">
                        <span className="font-black text-xs text-slate-700 underline decoration-blue-200 decoration-4">{s.code}: {s.name}</span>
                        <Trash2 className="text-slate-300 hover:text-red-500 cursor-pointer" size={16} />
                    </div>
                ))}
             </div>
          </div>
        )}

        {/* PROCTORS TAB */}
        {activeTab === 'proctors' && (
          <div className="space-y-6">
            <div className="flex gap-4 p-6 bg-emerald-50 rounded-3xl border border-emerald-100">
                <input 
                    value={pName} 
                    onChange={(e) => setPName(e.target.value)}
                    placeholder="ENTER FULL NAME" 
                    className="flex-1 p-4 rounded-2xl shadow-sm text-xs font-black border-none" 
                />
                <button onClick={addProctor} className="bg-emerald-600 text-white px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl shadow-emerald-200 hover:scale-95 transition-all">Add Proctor</button>
            </div>
            {proctors.map(p => (
                <div key={p.id} className="p-6 border border-slate-200 rounded-3xl bg-white flex justify-between items-center shadow-sm">
                    <span className="font-black text-slate-800 tracking-tight">{p.name}</span>
                    <div className="flex gap-2">
                        <span className="bg-emerald-100 text-emerald-700 text-[9px] font-black px-3 py-1 rounded-full uppercase">Available</span>
                        <Trash2 className="text-slate-200 hover:text-red-500" size={18} />
                    </div>
                </div>
            ))}
          </div>
        )}

        {/* GENERATE TAB: THE "SMART ENGINE" BOX */}
        {activeTab === 'generate' && (
          <div className="bg-slate-900 rounded-[3rem] p-12 text-white relative overflow-hidden shadow-[0_35px_60px_-15px_rgba(0,0,0,0.3)]">
            <div className="absolute top-0 right-0 p-12 opacity-5"><Play size={200} fill="currentColor" /></div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-16 relative z-10">

              {/* LEFT: TIME & DATE LOGIC */}
              <div className="space-y-10">
                <div>
                  <h4 className="text-blue-400 font-black text-[10px] uppercase tracking-[0.4em] mb-6 flex items-center gap-2">
                    <Clock size={14} /> Temporal Window
                  </h4>
                  <div className="space-y-4">
                    <div className="flex justify-between items-center bg-slate-800/50 p-4 rounded-2xl border border-slate-700">
                        <span className="text-xs font-bold text-slate-400">Total Exam Days</span>
                        <input type="number" value={examDays} onChange={(e) => handleExamDayChange(e.target.value)} className="bg-slate-900 w-16 text-center py-2 rounded-lg font-black" />
                    </div>
                    {/* DYNAMIC DATE BOXES */}
                    <div className="grid grid-cols-1 gap-3 max-h-40 overflow-y-auto pr-2 custom-scrollbar">
                        {examDates.map((d, i) => (
                           <div key={i} className="flex items-center gap-3 bg-slate-800/30 p-3 rounded-xl border border-slate-700">
                               <span className="text-[10px] font-black text-slate-500">DAY {i+1}</span>
                               <input type="date" value={d} onChange={(e) => updateDateAt(i, e.target.value)} className="bg-transparent flex-1 outline-none text-xs font-bold text-blue-200" />
                           </div>
                        ))}
                    </div>
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-6">
                    <div>
                        <span className="text-[10px] font-black text-slate-500 uppercase block mb-3">Time Start</span>
                        <input type="time" value={startTime} onChange={(e) => setStartTime(e.target.value)} className="w-full bg-slate-800 border border-slate-700 p-4 rounded-2xl font-black text-blue-400" />
                    </div>
                    <div>
                        <span className="text-[10px] font-black text-slate-500 uppercase block mb-3">Time End</span>
                        <input type="time" value={endTime} onChange={(e) => setEndTime(e.target.value)} className="w-full bg-slate-800 border border-slate-700 p-4 rounded-2xl font-black text-blue-400" />
                    </div>
                </div>
              </div>

              {/* RIGHT: RESOURCE CONFIG */}
              <div className="space-y-10">
                <div>
                   <h4 className="text-emerald-400 font-black text-[10px] uppercase tracking-[0.4em] mb-6 flex items-center gap-2">
                    <ShieldCheck size={14} /> Resource Allocation
                  </h4>
                  <div className="space-y-6">
                    <div className="flex justify-between items-center">
                        <span className="text-xs font-bold text-slate-300 uppercase">Target Year</span>
                        <select value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)} className="bg-slate-800 border-none p-3 rounded-xl font-black text-xs w-32">
                            {[1,2,3,4,5].map(y => <option key={y} value={y}>YR {y}</option>)}
                        </select>
                    </div>
                    <div className="flex justify-between items-center">
                        <span className="text-xs font-bold text-slate-300 uppercase">Total Sections</span>
                        <input type="number" value={sectionCount} onChange={(e) => setSectionCount(e.target.value)} className="bg-slate-800 border-none p-3 rounded-xl font-black text-xs w-20 text-center" />
                    </div>

                    {/* FALLBACK BADGES */}
                    <div className="pt-6 border-t border-slate-800 space-y-4">
                        <div className="flex justify-between items-center">
                            <span className="text-[10px] font-black text-slate-500 uppercase">Proctor Logic</span>
                            <div className="flex bg-slate-800 p-1 rounded-xl">
                                <button onClick={() => setProctorSource("Department")} className={`px-4 py-2 text-[9px] font-black rounded-lg ${proctorSource === 'Department' ? 'bg-blue-600 text-white' : 'text-slate-500'}`}>DEPT</button>
                                <button onClick={() => setProctorSource("Global")} className={`px-4 py-2 text-[9px] font-black rounded-lg ${proctorSource === 'Global' ? 'bg-blue-600 text-white' : 'text-slate-500'}`}>GLOBAL</button>
                            </div>
                        </div>
                        <div className="flex justify-between items-center">
                            <span className="text-[10px] font-black text-slate-500 uppercase">Room Logic</span>
                            <div className="flex bg-slate-800 p-1 rounded-xl">
                                <button onClick={() => setRoomSource("Department")} className={`px-4 py-2 text-[9px] font-black rounded-lg ${roomSource === 'Department' ? 'bg-amber-600 text-white' : 'text-slate-500'}`}>DEPT</button>
                                <button onClick={() => setRoomSource("Global")} className={`px-4 py-2 text-[9px] font-black rounded-lg ${roomSource === 'Global' ? 'bg-amber-600 text-white' : 'text-slate-500'}`}>GLOBAL</button>
                            </div>
                        </div>
                    </div>
                  </div>
                </div>

                <button onClick={handleGenerateClick} className="w-full bg-blue-600 hover:bg-blue-500 py-6 rounded-[2rem] font-black text-xs uppercase tracking-[0.3em] flex items-center justify-center gap-4 transition-all active:scale-95 shadow-[0_20px_40px_-15px_rgba(37,99,235,0.4)]">
                    <Play size={20} fill="currentColor" /> Run Conflict-Free Engine
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DepartmentCard;
